category.scss:
#main-content { 
    > .container{
        padding: 0;
        max-width: 100%;
        width: 100%;
        margin: 0;
    }
}

#main-content .breadcrumbs{
    text-align: left;
}

#facetedSearch-navList{
    margin-top: 0;
    .accordion-navigation{
        margin-bottom: 0 !important;
    }
}

.page{
    margin: 0 !important;
}

.twelve-category-page {
    display: block;
    margin-left: 0;
    margin-right: 0;
    max-width: none;
    overflow: hidden;
    width: 100%;
}

.twelve-category-page__catalogue {
    display: grid;
    grid-template-columns: 240px minmax(0, 1fr);
    gap: 48px;
    max-width: 1512px;
    padding-bottom: 80px;
}

.twelve-category-page .page-sidebar,
.twelve-category-page .page-content,
.twelve-category-page .page-region {
    float: none;
    margin: 0;
    padding: 0;
    width: auto;
}

.twelve-category-page .page-region {
    grid-column: 1 / -1;
}

.twelve-category-toolbar {
    align-items: center;
    display: flex;
    justify-content: space-between;
    margin: 0 0 28px;
    min-height: 44px;
}

.twelve-category-toolbar__count {
    color: #111;
    font-family: var(--sans-ext);
    font-size: 12px;
    font-weight: 500;
    letter-spacing: .025em;
    margin: 0;
    text-transform: uppercase;
}

.twelve-category-toolbar .actionBar {
    margin: 0;
}

.twelve-category-toolbar .form-field {
    align-items: center;
    display: flex;
    gap: 12px;
    margin: 0;
}

.twelve-category-toolbar .form-label {
    color: #111;
    font-family: var(--sans-ext);
    font-size: 10px;
    letter-spacing: .08em;
    margin: 0;
    text-transform: uppercase;
}

.twelve-category-toolbar .form-select {
    border: 0;
    border-bottom: 1px solid #111;
    border-radius: 0;
    color: #111;
    font-size: 12px;
    min-width: 150px;
    padding-left: 0;
}

.twelve-category-page .productGrid {
    display: grid;
    gap: 48px 16px;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    margin: 0;
}

.twelve-category-page .productGrid::before,
.twelve-category-page .productGrid::after {
    display: none;
}

.twelve-category-page .productGrid .product,
.twelve-category-page .page-sidebar + .twelve-category-page__products .productGrid .product {
    display: block;
    padding: 0;
    width: 100%;
}

.twelve-category-page .card {
    display: flex;
    flex-direction: column;
    height: 100%;
    margin: 0;
    overflow: visible;
}

.twelve-category-page .card-figure {
    background: #edebe7;
    margin: 0;
    // overflow: hidden;
}

.twelve-category-page .card-img-container {
    height: 450px;
    background: #ffffff;
    max-width: none;
    position: relative;
    @media (max-width: 767px) {
        height: 350px;
    }
    @media (max-width: 479px) {
        height: 220px;
    }
}

.twelve-category-page .card-img-container::after {
    display: none;
}

.twelve-category-page .card-image {
    display: block;
    height: 100%;
    object-fit: contain;
    width: 100%;
}

.twelve-category-page .card-body {
    gap: 5px;
    padding: 15px 0 0;
}

.twelve-category-page .card-brand {
    color: #686868;
    font-family: var(--sans-ext);
    font-size: 12px;
    font-weight: 500;
    letter-spacing: .025em;
    margin: 0;
    text-transform: uppercase;
}

.twelve-category-page .card-title {
    font-family: var(--serif);
    font-size: 16.5px;
    font-weight: 400;
    line-height: 1.25;
    margin: 0;
}

.twelve-category-page .card-title a {
    color: #111;
    text-decoration: none;
}

.twelve-category-page .card-title a:hover,
.twelve-category-page .card-title a:focus {
    color: #111;
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
}

.twelve-category-page .card-price-line {
    align-items: baseline;
    gap: 9px;
    margin-top: 2px;
}

.twelve-category-page .card-price {
    color: #111;
    font-family: var(--sans);
    font-size: 16px;
    font-weight: 300;
    margin: 0;
}

.twelve-category-page .card-price-note {
    color: #000000;
    font-family: var(--sans);
    font-size: 14px;
    margin: 0;
    text-transform: uppercase;
}

.twelve-category-page .card {
    position: relative;
}

.twelve-category-page .card-save {
    background: rgba(255, 255, 255, .82);
    border-radius: 0;
}

.twelve-category-page .sale-flag-side,
.twelve-category-page .sold-out-flag-side {
    border-radius: 0;
    font-family: var(--sans-ext);
    font-size: 8.5px;
    font-weight: 500;
    height: auto;
    letter-spacing: .025em;
    line-height: 1;
    padding: 5px 9px;
    text-transform: uppercase;
}

.twelve-category-page .sustainability-flag {
    background: #008568;
    border-radius: 0;
    color: #ffffff;
    left: 12px;
    min-width: 0;
    padding: 7px 10px;
    top: 12px;
    z-index: 2;

    .sale-text {
        color: inherit;
        font-family: var(--sans-ext);
        font-size: 14px;
        font-weight: 700;
        letter-spacing: 0;
        line-height: 1;
        text-transform: uppercase;
    }
}

.twelve-category-page .product:hover .sustainability-flag,
.twelve-category-page .card:hover .sustainability-flag {
    background: #008568 !important;
    color: #ffffff;

    .sale-text {
        color: #ffffff !important;
    }
}

.twelve-category-pagination {
    border-top: 1px solid #ddd;
    margin-top: 64px;
    padding-top: 28px;
}

.twelve-category-load-more {
    align-items: center;
    display: flex;
    flex-direction: column;
    gap: 18px;
    margin: 0 auto;
    padding: 64px 0 108px;
    text-align: center;
}

.twelve-category-load-more__count {
    color: #555;
    font-family: var(--sans-ext);
    font-size: 13px;
    margin: 0;
    text-transform: uppercase;
}

.twelve-category-load-more__track {
    background: #ddd;
    display: block;
    height: 1px;
    margin: 0;
    width: 180px;
}

.twelve-category-load-more__track i {
    background: #111;
    display: block;
    height: 1px;
    transition: width .5s ease;
    width: 0;
}

.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button {
    background: transparent !important;
    border: 1px solid #000 !important;
    border-radius: 0 !important;
    color: #000 !important;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: var(--sans-ext) !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    height: auto;
    letter-spacing: .025em !important;
    line-height: 1 !important;
    margin: 0 !important;
    min-height: 48px !important;
    overflow: hidden;
    padding: 17px 30px !important;
    position: relative;
    text-transform: uppercase !important;
    transition: color .42s cubic-bezier(.22, 1, .36, 1), border-color .42s cubic-bezier(.22, 1, .36, 1);
}

.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button::after {
    background: #000;
    content: "";
    inset: 0;
    position: absolute;
    transform: translateY(101%);
    transition: transform .42s cubic-bezier(.22, 1, .36, 1);
    z-index: 0;
}

.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button > span {
    position: relative;
    z-index: 1;
}

.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button:hover,
.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button:focus {
    background: transparent !important;
    color: #fff !important;
}

.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button:hover::after,
.twelve-category-page .twelve-category-load-more .twelve-category-load-more__button:focus::after {
    transform: translateY(0);
}

@media (max-width: 980px) {
    .twelve-category-page__catalogue {
        gap: 32px;
        grid-template-columns: 200px minmax(0, 1fr);
        padding-inline: 32px;
    }

    .twelve-category-page .productGrid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 991px) {
    .twelve-category-page__catalogue {
        display: block;
        box-sizing: border-box;
        margin: 0 !important;
        max-width: none !important;
        padding: 0 20px 88px !important;
        width: 100% !important;
    }

    .twelve-category-page .page-sidebar {
        position: static;
    }

    .twelve-category-page .facetedSearch-toggle {
        align-items: center;
        background: #fff;
        border: 0;
        border-right: 1px solid #ddd;
        border-top: 1px solid #ddd;
        border-top-left-radius: 0;
        border-bottom-left-radius: 28px;
        box-sizing: border-box;
        bottom: 0;
        display: flex;
        font-family: var(--sans-ext);
        font-size: 10px;
        font-weight: 500;
        height: 54px;
        justify-content: center;
        gap: 8px;
        left: 0;
        letter-spacing: .025em;
        margin: 0;
        padding: 0;
        position: fixed;
        text-transform: uppercase;
        width: 50%;
        z-index: 25;
    }

    .twelve-category-page .facetedSearch-toggle-text {
        display: inline-flex;
        flex: 0 0 auto;
        font-size: 0;
        width: auto;
    }

    .twelve-category-page .facetedSearch-toggle-text::after {
        color: #111;
        content: "Filter";
        font-family: var(--sans-ext);
        font-size: 11px;
        text-transform: uppercase;
    }

    .twelve-mobile-filter-count {
        color: #111;
        display: inline-block;
        flex: 0 0 auto;
        font-family: var(--sans-ext);
        font-size: 10px;
        font-weight: 500;
        line-height: 1;
    }

    .twelve-mobile-filter-count:empty {
        display: none;
    }

    .twelve-category-page .facetedSearch-toggle-indicator {
        display: none;
    }

    .twelve-category-page .facetedSearch-navList {
        background: #fff;
        border-radius: 0;
        bottom: 0;
        box-shadow: 0 -8px 30px rgba(0, 0, 0, .2);
        display: none !important;
        flex-direction: column;
        left: 0;
        max-height: calc(100vh - 115px);
        overflow: hidden;
        padding: 0;
        position: fixed;
        right: 0;
        top: auto;
        z-index: 131;
    }

    .twelve-category-page .facetedSearch-navList.is-open {
        display: flex !important;
        animation: twelve-filter-sheet-in .32s cubic-bezier(.22, 1, .36, 1);
    }

    .twelve-category-page .facetedSearch-navList.is-open > .twelve-mobile-filter-head {
        display: flex !important;
        flex: 0 0 76px;
        opacity: 1;
        position: relative;
        visibility: visible;
        z-index: 2;
    }

    @keyframes twelve-filter-sheet-in {
        from {
            opacity: 0;
            transform: translateY(18px);
        }

        to {
            opacity: 1;
            transform: translateY(0);
        }
    }

    .twelve-mobile-filter-head {
        align-items: center;
        border-bottom: 1px solid #ddd;
        display: flex;
        flex: none;
        justify-content: space-between;
        min-height: 76px;
        padding: 18px 20px;
    }

    .twelve-mobile-filter-head > span {
        font-family: var(--sans-ext);
        font-size: 10px;
        font-weight: 500;
        letter-spacing: .025em;
        text-transform: uppercase;
    }

    .twelve-mobile-filter-head button {
        background: transparent;
        border: 0;
        color: #111;
        font-size: 20px;
        font-weight: 300;
        height: 24px;
        line-height: 1;
        padding: 0;
        width: 24px;
    }

    .twelve-category-page .facetedSearch-navList .accordion {
        flex: 1 1 auto;
        overflow-y: auto;
        padding: 8px 20px 24px;
    }

    .twelve-category-page .facetedSearch-navList .accordion-block {
        border-bottom: 1px solid #ddd;
        margin: 0;
        padding: 0 0 18px;
    }

    .twelve-category-page .facetedSearch-navList .accordion-block:last-child {
        border-bottom: 0;
    }

    .twelve-category-page .facetedSearch-navList .accordion-heading {
        display: block;
        height: auto;
        margin: 0;
    }

    .twelve-category-page .facetedSearch-navList .accordion-navigation {
        border: 0 !important;
        color: #111;
        display: block;
        font-family: var(--sans-ext) !important;
        font-size: 10px !important;
        font-weight: 500 !important;
        height: auto !important;
        letter-spacing: .025em !important;
        line-height: 1 !important;
        min-height: 0;
        pointer-events: none;
        padding: 20px 0 14px !important;
        text-align: left;
        text-transform: uppercase !important;
        width: 100%;
    }

    .twelve-category-page .facetedSearch-navList .accordion-navigation > span:last-child,
    .twelve-category-page .facetedSearch-navList .accordion-indicator,
    .twelve-category-page .facetedSearch-navList .facetedSearch-clearLink {
        display: none !important;
    }

    .twelve-category-page .facetedSearch-navList .accordion-content {
        border: 0;
        display: block !important;
        opacity: 1;
        padding: 0;
        pointer-events: auto;
        position: static;
        transform: none;
        visibility: visible;
    }

    .twelve-category-page .facetedSearch-navList .accordion-content::before {
        display: none;
    }

    .twelve-category-page .facetedSearch-navList .navList-action {
        align-items: center;
        color: #111;
        display: flex;
        font-family: var(--serif);
        font-size: 15px;
        line-height: 1.25;
        min-height: 34px;
        padding-bottom: 7px;
        padding-right: 2px;
        padding-top: 7px;
        transition: color .2s ease, opacity .2s ease;
        width: 100%;
    }

    .twelve-category-page .facetedSearch-navList .twelve-facet-option-count {
        color: #777;
        flex: none;
        font-family: var(--sans);
        font-size: 11px;
        margin-left: auto;
        padding-left: 12px;
    }

    .twelve-category-page .facetedSearch-navList [data-faceted-search-range] {
        margin: 0;
    }

    .twelve-category-page .facetedSearch-navList .form-minMaxRow {
        align-items: center;
        display: flex;
        gap: 10px;
        margin: 6px 0 0;
        width: 100%;
    }

    .twelve-category-page .facetedSearch-navList .form-minMaxRow .form-field {
        flex: 1 1 0;
        margin: 0;
        min-width: 0;
        padding: 0;
        width: auto;
    }

    .twelve-category-page .facetedSearch-navList .form-minMaxRow .form-input {
        background: #fff;
        border: 1px solid #c9c9c9;
        border-radius: 0;
        box-sizing: border-box;
        font-family: var(--sans);
        font-size: 13px;
        height: 38px;
        line-height: 1;
        padding: 10px;
        width: 100%;
    }

    .twelve-category-page .facetedSearch-navList .form-minMaxRow .button {
        background: #fff;
        border: 1px solid #c9c9c9;
        color: #666;
        font-family: var(--sans);
        font-size: 13px;
        height: 38px;
        margin: 0;
        min-height: 38px;
        padding: 0 12px;
        text-transform: none;
        width: 74px;
    }

    .twelve-category-page .facetedSearch-navList .form-minMaxRow .form-input:focus,
    .twelve-category-page .facetedSearch-navList .form-minMaxRow .button:hover,
    .twelve-category-page .facetedSearch-navList .form-minMaxRow .button:focus {
        border-color: #111;
        outline: 0;
    }

    .twelve-category-page .facetedSearch-navList .navList-action:hover,
    .twelve-category-page .facetedSearch-navList .navList-action:focus {
        color: #111;
        opacity: .62;
    }

    .twelve-category-page .facetedSearch-navList .navList-action::before {
        background: #fff;
        border: 1px solid #c9c9c9;
        border-radius: 0;
        box-sizing: border-box;
        height: 15px;
        margin-top: 0;
        top: 9px;
        transform: none;
        width: 15px;
    }

    .twelve-category-page .facetedSearch-navList .navList-action::after {
        left: 4px;
    }

    .twelve-category-page .facetedSearch-navList .navList-action.is-selected::before {
        background: #111;
        border-color: #111;
    }

    .twelve-category-page .facetedSearch-navList .navList-action.is-selected::after {
        background: transparent;
        background-image: none;
        border: 0;
        border-bottom: 1.5px solid #fff;
        border-right: 1.5px solid #fff;
        content: "";
        height: 9px;
        left: 4px;
        margin: 0;
        margin-top: 0;
        opacity: 1;
        position: absolute;
        top: 10px;
        transform: rotate(42deg);
        width: 5px;
    }

    .twelve-category-page .facetedSearch-navList .twelve-facet-count {
        display: none;
    }

    .twelve-category-page .facetedSearch-navList .twelve-facet-footer {
        display: none;
    }

    .twelve-mobile-filter-foot {
        border-top: 1px solid #ddd;
        display: flex;
        flex: none;
        gap: 10px;
        padding: 16px 20px 20px;
    }

    .twelve-mobile-filter-foot .button {
        background: #000 !important;
        border: 1px solid #000 !important;
        color: #fff !important;
        flex: 1;
        font-family: var(--sans-ext);
        font-size: 10px;
        font-weight: 500;
        letter-spacing: .025em;
        margin: 0;
        min-height: 48px;
        overflow: hidden;
        position: relative;
        text-transform: uppercase;
        transition: color .35s cubic-bezier(.22, .61, .36, 1);
    }

    .twelve-mobile-filter-foot .button:first-child {
        background: #fff !important;
        color: #111 !important;
    }

    .twelve-mobile-filter-foot .button::after {
        background: #fff;
        content: "";
        inset: 0;
        position: absolute;
        transform: translateY(101%);
        transition: transform .35s cubic-bezier(.22, .61, .36, 1);
        z-index: 0;
    }

    .twelve-mobile-filter-foot .button:first-child::after {
        background: #000;
    }

    .twelve-mobile-filter-foot .button > span {
        position: relative;
        z-index: 1;
    }

    .twelve-mobile-filter-foot .button:hover,
    .twelve-mobile-filter-foot .button:focus {
        color: #111 !important;
    }

    .twelve-mobile-filter-foot .button:first-child:hover,
    .twelve-mobile-filter-foot .button:first-child:focus {
        color: #fff !important;
    }

    .twelve-mobile-filter-foot .button:hover::after,
    .twelve-mobile-filter-foot .button:focus::after {
        transform: translateY(0);
    }

    .twelve-mobile-filter-foot .button:last-child {
        flex-grow: 1.6;
    }

    .twelve-category-page .page-sidebar .actionBar {
        display: none;
    }

    .twelve-mobile-sort-toggle {
        align-items: center;
        background: #fff;
        border: 0;
        border-top: 1px solid #ddd;
        border-bottom-right-radius: 28px;
        box-sizing: border-box;
        bottom: 0;
        display: flex;
        font-family: var(--sans-ext);
        font-size: 10px;
        font-weight: 500;
        height: 54px;
        justify-content: center;
        letter-spacing: .025em;
        position: fixed;
        right: 0;
        text-transform: uppercase;
        width: 50%;
        z-index: 25;
    }

    .twelve-category-page .facetedSearch-toggle:hover,
    .twelve-category-page .facetedSearch-toggle:focus,
    .twelve-mobile-sort-toggle:hover,
    .twelve-mobile-sort-toggle:focus {
        background: #fff;
        color: #111;
    }

    .twelve-mobile-sheet-scrim {
        background: rgba(0, 0, 0, .48);
        backdrop-filter: blur(2px);
        border: 0;
        display: block;
        inset: 0;
        opacity: 0;
        pointer-events: none;
        position: fixed;
        transition: opacity .3s ease;
        width: 100%;
        z-index: 130;
    }

    body.twelve-mobile-sheet-open .twelve-mobile-sheet-scrim {
        opacity: 1;
        pointer-events: auto;
    }

    .twelve-mobile-sort-sheet {
        background: #fff;
        border-radius: 0;
        bottom: 0;
        box-shadow: 0 -8px 30px rgba(0, 0, 0, .2);
        display: flex;
        flex-direction: column;
        left: 0;
        max-height: 380px;
        overflow: hidden;
        position: fixed;
        right: 0;
        transform: translateY(100%);
        transition: transform .42s cubic-bezier(.22, 1, .36, 1);
        z-index: 131;
    }

    .twelve-mobile-sort-sheet.is-open {
        transform: translateY(0);
    }

    .twelve-mobile-sort-sheet.is-open > .twelve-mobile-filter-head {
        display: flex !important;
        flex: 0 0 76px;
        opacity: 1;
        position: relative;
        visibility: visible;
        z-index: 2;
    }

    .twelve-mobile-sort-list {
        overflow-y: auto;
        padding: 6px 20px 20px;
    }

    .twelve-mobile-sort-list button {
        align-items: center;
        background: transparent;
        border: 0;
        border-bottom: 1px solid #ddd;
        display: flex;
        font-family: var(--serif);
        font-size: 16px;
        justify-content: space-between;
        line-height: 1.25;
        min-height: 50px;
        padding: 12px 0;
        text-align: left;
        width: 100%;
    }

    .twelve-mobile-sort-list button:hover,
    .twelve-mobile-sort-list button:focus {
        background: transparent;
        color: #183b59;
    }

    .twelve-mobile-sort-list button[aria-checked="true"]::after {
        border-bottom: 1.5px solid #111;
        border-right: 1.5px solid #111;
        content: "";
        height: 11px;
        margin-right: 3px;
        transform: rotate(42deg);
        width: 6px;
    }

    .twelve-category-toolbar {
        min-height: 40px;
    }

    .twelve-category-page .page-sidebar .actionBar {
        background: #fff;
        bottom: 0;
        height: 54px;
        margin: 0;
        position: fixed;
        right: 0;
        width: 50%;
