            border-radius: 0;
            margin: 0;
            height: auto;
            padding: 10px;
            box-shadow: none;
            background-position: right center;
            color: #000;
            font-size: 15px;
        }
    }

    .form-actions{
        margin: 0;
        text-align: left;
        width: 100%;
        display: flex;
        align-items: center;
        flex-wrap: wrap;
    }
    
    .button{
        width: auto;
        margin: 0;
        padding: 10px 16px;
        border-radius: 6px;
        font-family: var(--sans-ext);
        font-size: 14px;
        line-height: 16px;
        font-weight: 400;
        text-align: left;
        text-transform: none;
        + .button{ 
            margin:0 0 0 15px;
        }
        
        &[disabled]{
            opacity: 0.6;
            pointer-events: none;
        }
    }
    
    .button--primary{
        background: #000000;
        border-color: #000000;
        color: #fff;
        &:hover{
            border-color: #000000;
            background: #ffffff;color:#000000;
        }
    }

    .buttonSecondary{
        border-color: #CCCCCC;
        + .buttonSecondary{
            margin-left: 15px;
        }
        &:hover{
            border-color: #CCCCCC;
            color: #000000;
        }
    }

    .view-password-action {
        position: relative;
        .view-password-icon{
            position: absolute;
            right: 5px;
            width: 30px;
            height: 30px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            top: 5px;
            &:hover, &.is-active{
                svg{
                    path{
                        fill: #000000;
                    }
                }
            }
        }
    }

    /* Change the white to any color */
    input:-webkit-autofill,
    input:-webkit-autofill:hover, 
    input:-webkit-autofill:focus, 
    input:-webkit-autofill:active{
        -webkit-box-shadow: 0 0 0 30px #fff inset !important;
    }
    
    @include md-phone {
        padding: 0; 
    }

}

